import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.verify;

/**
 * Unit tests for ParserMinimalBase#reportOverflowLong.
 * Since the method is protected and calls another protected method _reportError,
 * we use a Spy to intercept the error reporting and verify the logic.
 */
public class ParserMinimalBase_reportOverflowLong_TriageGen1Test {

    private ParserMinimalBase parserMinimalBase;
    private ParserMinimalBase spyParser;

    @Before
    public void setUp() {
        // ParserMinimalBase is abstract, so we must use a concrete subclass or a mock/spy approach.
        // We use Mockito to create a spy of the abstract class.
        spyParser = spy(Mockito.mock(ParserMinimalBase.class, Mockito.withSettings().useConstructor(0).defaultAnswer(Mockito.CALLS_REAL_METHODS)));
    }

    /**
     * Tests the successful execution and correct message formatting of reportOverflowLong.
     * This covers the line coverage and the logic inside the String.format.
     */
    @Test
    public void testReportOverflowLong_Success() throws Exception {
        String numDesc = "9223372036854775808"; // Long.MAX_VALUE + 1

        // Access the protected method via reflection or by using the spy
        Method method = ParserMinimalBase.class.getDeclaredMethod("reportOverflowLong", String.class);
        method.setAccessible(true);

        // We need to ensure _reportError is caught to prevent the exception from breaking the test 
        // while still verifying the content.
        // Since _reportError is protected, we use doNothing on the spy.
        doNothing().when(spyParser)._reportError(anyString());

        // Execute
        method.invoke(spyParser, numDesc);

        // Verify that _reportError was called with the expected formatted string.
        // The format is: "Numeric value (%s) out of range of long (%d - %s)"
        // _longIntegerDesc(numDesc) is called internally.
        // Note: Since we are spying on a mock, we rely on the real method implementation of reportOverflowLong.

        // We use a capture or just verify the pattern. 
        // Given the implementation, it calls _reportError(String msg).
        verify(spyParser)._reportError(org.mockito.ArgumentMatchers.contains("Numeric value"));
        verify(spyParser)._reportError(org.mockito.ArgumentMatchers.contains("out of range of long"));
    }

    /**
     * Tests the scenario where reportOverflowLong is called with a null description.
     */
    @Test
    public void testReportOverflowLong_NullDescription() throws Exception {
        Method method = ParserMinimalBase.class.getDeclaredMethod("reportOverflowLong", String.class);
        method.setAccessible(true);

        doNothing().when(spyParser)._reportError(anyString());

        method.invoke(spyParser, (String) null);

        verify(spyParser)._reportError(org.mockito.ArgumentMatchers.contains("Numeric value (null)"));
    }

    /**
     * Tests that the method correctly throws an IOException if _reportError throws one.
     * This ensures the 'throws IOException' part of the signature is respected.
     */
    @Test(expected = Exception.class) // Reflection wraps the JsonParseException in an InvocationTargetException
    public void testReportOverflowLong_ThrowsException() throws Exception {
        Method method = ParserMinimalBase.class.getDeclaredMethod("reportOverflowLong", String.class);
        method.setAccessible(true);

        // Force _reportError to throw an exception
        doNothing().when(spyParser)._longIntegerDesc(anyString());
        // We simulate a failure in the error reporting mechanism
        doThrow(new IOException("Simulated IO Error")).when(spyParser)._reportError(anyString());

        method.invoke(spyParser, "123");
    }
}
